const scope = self.registration.scope;
const budget = 50 * 1024 * 1024;
let opening;
function database() {
  if (!opening) opening = new Promise((resolve, reject) => {
    const request = indexedDB.open('mechanical-course:' + scope, 1);
    request.onupgradeneeded = () => {
      request.result.createObjectStore('body');
      request.result.createObjectStore('meta', {keyPath:'path'});
    };
    request.onerror = request.onblocked = () => reject(new Error('Storage unavailable'));
    request.onsuccess = () => {
      const db = request.result;
      db.onversionchange = () => { db.close(); opening = null; };
      resolve(db);
    };
  }).catch(error => { opening = null; throw error; });
  return opening;
}

async function transaction(action) {
  const db = await database();
  return new Promise((resolve,reject) => {
    const tx = db.transaction(['meta','body'], 'readwrite');
    let value;
    tx.oncomplete = () => resolve(value);
    tx.onabort = () => reject(tx.error || new Error('Cache aborted'));
    action(tx.objectStore('meta'), tx.objectStore('body'), result => { value = result; });
  });
}

function lookup(path) {
  return transaction((meta,body,finish) => {
    const request = meta.get(path);
    request.onsuccess = () => {
      const entry = request.result;
      if (!entry || entry.hash !== files[path]) return;
      const read = body.get(path);
      read.onsuccess = () => {
        if (!read.result) return;
        meta.put({...entry, used:Date.now()});
        finish(new Response(read.result, {headers:{'Content-Type':entry.type}}));
      };
    };
  });
}

function prune(meta, body, rows, limit) {
  let total = rows.reduce((sum,row) => sum + row.size, 0);
  rows.sort((a,b) => a.used-b.used);
  for (const row of rows) {
    if (total <= limit && files[row.path] === row.hash) continue;
    body.delete(row.path);
    meta.delete(row.path);
    total -= row.size;
  }
}

async function store(path, response) {
  const blob = await response.blob();
  if (blob.size > budget) return;
  let bytes = await blob.arrayBuffer();
  if (/\.(html|css|js)$/.test(path)) bytes = new TextEncoder().encode(new TextDecoder().decode(bytes).replace(/\r\n/g,'\n'));
  const digest = await crypto.subtle.digest('SHA-256', bytes);
  const hash = Array.from(new Uint8Array(digest), b => b.toString(16).padStart(2,'0')).join('');
  if (hash !== files[path]) return;
  const write = () => transaction((meta,body) => {
    const list = meta.getAll();
    list.onsuccess = () => {
      prune(meta,body,list.result.filter(row => row.path !== path),budget-blob.size);
      body.put(blob,path);
      meta.put({path,hash,size:blob.size,type:blob.type,used:Date.now()});
    };
  });
  try { await write(); } catch (error) {
    if (error.name !== 'QuotaExceededError') throw error;
    await transaction((meta,body) => {
      const list = meta.getAll();
      list.onsuccess = () => prune(meta,body,list.result,
        Math.max(0,list.result.reduce((sum,row)=>sum+row.size,0)-Math.max(blob.size,4*1024*1024)));
    });
    await write();
  }
}

self.addEventListener('activate', event => event.waitUntil((async () => {
  await transaction((meta,body) => {
    const list = meta.getAll();
    list.onsuccess = () => prune(meta,body,list.result,budget);
  }).catch(()=>{});
  await self.clients.claim();
})()));

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET' || req.headers.has('Range') || !req.url.startsWith(scope)) return;
  let path = req.url.slice(scope.length);
  if (!path || path.endsWith('/')) path += 'index.html';
  if (!Object.hasOwn(files,path)) return;
  event.respondWith((async () => {
    const cached = await lookup(path).catch(() => null);
    if (cached) return cached;
    const response = await fetch(req,{cache:'no-cache'});
    if (response.status === 200 && !response.headers.has('Content-Range'))
      event.waitUntil(store(path,response.clone()).catch(()=>{}));
    return response;
  })());
});

